<script>
    // Safely get value, prioritizing the first element if it's an array [value, desc]
    function SafeGetValue(value, defaultValue = "N/A") {
        if (value === undefined || value === null) {
            return defaultValue;
        }
        if (Array.isArray(value) && value.length > 0) {
            return String(value[0]);
        }
        return String(value);
    }

    // Initialization function to populate affection values
    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data || !messages[0].data.stat_data) {
                console.warn("Status bar: Could not retrieve stat_data from message. Displaying N/A.");
                // Set all to N/A if data is missing
                document.getElementById('swq-affection').innerText = 'N/A';
                document.getElementById('srx-affection').innerText = 'N/A';
                document.getElementById('sxx-affection').innerText = 'N/A';
                document.getElementById('sme-affection').innerText = 'N/A';
                document.getElementById('sff-affection').innerText = 'N/A';
                return;
            }
            const statData = messages[0].data.stat_data;

            document.getElementById('swq-affection').innerText = statData.苏婉琴 ? SafeGetValue(statData.苏婉琴.好感度, '0') : 'N/A';
            document.getElementById('srx-affection').innerText = statData.苏若雪 ? SafeGetValue(statData.苏若雪.好感度, '0') : 'N/A';
            document.getElementById('sxx-affection').innerText = statData.苏小小 ? SafeGetValue(statData.苏小小.好感度, '0') : 'N/A';
            document.getElementById('sme-affection').innerText = statData.孙媚儿 ? SafeGetValue(statData.孙媚儿.好感度, '0') : 'N/A';
            document.getElementById('sff-affection').innerText = statData.孙芳芳 ? SafeGetValue(statData.孙芳芳.好感度, '0') : 'N/A';

        } catch (error) {
            console.error("Error initializing status display:", error);
            document.getElementById('swq-affection').innerText = 'Err';
            document.getElementById('srx-affection').innerText = 'Err';
            document.getElementById('sxx-affection').innerText = 'Err';
            document.getElementById('sme-affection').innerText = 'Err';
            document.getElementById('sff-affection').innerText = 'Err';
        }
    }

    // Tab switching logic
    function setupTabs() {
        const tabButtons = document.querySelectorAll('.tab-button');
        const tabContents = document.querySelectorAll('.tab-content');

        tabButtons.forEach(button => {
            button.addEventListener('click', () => {
                // Remove active class from all buttons and contents
                tabButtons.forEach(btn => btn.classList.remove('active'));
                tabContents.forEach(content => content.classList.remove('active'));

                // Add active class to the clicked button and its corresponding content
                const targetTab = button.dataset.tab;
                button.classList.add('active');
                document.getElementById('tab-' + targetTab).classList.add('active');
            });
        });
    }

    // Initialize display and setup tabs when the DOM is ready
    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
        setupTabs();
    });

</script>
